            assertThat(header.value()).isEqualTo("Bearer token");
        }).// generated by the signer
        satisfiesOnlyOnce(header -> {
            assertThat(header.name()).isEqualTo("Host");
            assertThat(header.value()).isEqualTo("localhost:8080");
