            assertThat(header.value()).startsWith("AWS4-HMAC-SHA256 Credential=");
            assertThat(header.value()).contains("SignedHeaders=content-type;host;original-authorization;x-amz-content-sha256;x-amz-date");
        }).satisfiesOnlyOnce(header -> {
            assertThat(header.name()).isEqualTo("x-amz-content-sha256");
            assertThat(header.value()).isEqualTo("e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");
        }).satisfiesOnlyOnce(header -> assertThat(header.name()).isEqualTo("X-Amz-Date"));
    }
