void authenticateConflictingSigv4Headers() {
    HTTPRequest request = Mockito.mock(HTTPRequest.class);
    AuthSession delegate = Mockito.mock(AuthSession.class);
    when(delegate.authenticate(any())).thenReturn(ImmutableHTTPRequest.builder().method(HTTPMethod.GET).baseUri(URI.create("http://localhost:8080")).path("path").headers(HTTPHeaders.of(HTTPHeader.of("Content-Type", "application/json"), HTTPHeader.of("x-amz-content-sha256", "fake"), // corner case: conflicting header with same value as generated by the
    // signer: will not be relocated
    HTTPHeader.of("x-amz-content-sha256", "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"), HTTPHeader.of("X-Amz-Date", "fake"))).build());
    try (RESTSigV4AuthSession session = new RESTSigV4AuthSession(signer, delegate, awsProperties)) {
