@SuppressWarnings("MethodLength")
public void testTableAuth(String catalogToken, Map<String, String> credentials, Map<String, String> tableConfig, Map<String, String> expectedContextHeaders, Map<String, String> expectedTableHeaders, String oauth2ServerUri) {
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer " + catalogToken);
    Namespace namespace = Namespace.of("ns");
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    // inject the expected table config
    Answer<LoadTableResponse> addTableConfig = invocation -> {
        LoadTableResponse loadTable = (LoadTableResponse) invocation.callRealMethod();
        return LoadTableResponse.builder().withTableMetadata(loadTable.tableMetadata()).addAllConfig(loadTable.config()).addAllConfig(tableConfig).build();
    };
    Mockito.doAnswer(addTableConfig).when(adapter).execute(reqMatcher(HTTPMethod.POST, RESOURCE_PATHS.tables(namespace), expectedContextHeaders), eq(LoadTableResponse.class), any(), any());
    Mockito.doAnswer(addTableConfig).when(adapter).execute(reqMatcher(HTTPMethod.GET, RESOURCE_PATHS.table(TBL), expectedContextHeaders), eq(LoadTableResponse.class), any(), any());
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", credentials, ImmutableMap.of());
    RESTCatalog catalog = new RESTCatalog(context, (config) -> adapter);
    catalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, "ignored", "token", catalogToken, OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri));
    Schema expectedSchema = new Schema(required(1, "id", Types.IntegerType.get(), "unique ID"), required(2, "data", Types.StringType.get()));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TBL.namespace());
    }
    Table table = catalog.createTable(TBL, expectedSchema);
    assertThat(table.schema().asStruct()).as("Schema should match").isEqualTo(expectedSchema.asStruct());
    // the first load will send the token
    Table loaded = catalog.loadTable(TBL);
    assertThat(loaded.schema().asStruct()).as("Schema should match").isEqualTo(expectedSchema.asStruct());
    // refresh to force reload
    loaded.refresh();
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), catalogHeaders), eq(ConfigResponse.class), any(), any());
    // session client credentials flow
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, catalogHeaders), eq(OAuthTokenResponse.class), any(), any());
    // create table request
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, RESOURCE_PATHS.tables(namespace), expectedContextHeaders), eq(LoadTableResponse.class), any(), any());
    // if the table returned a bearer token or a credential, there will be no token request
    if (!tableConfig.containsKey("token") && !tableConfig.containsKey("credential")) {
        // token exchange to get a table token
        Mockito.verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, expectedContextHeaders), eq(OAuthTokenResponse.class), any(), any());
    }
    if (expectedContextHeaders.equals(expectedTableHeaders)) {
        // load table from catalog + refresh loaded table
        Mockito.verify(adapter, times(2)).execute(reqMatcher(HTTPMethod.GET, RESOURCE_PATHS.table(TBL), expectedTableHeaders), eq(LoadTableResponse.class), any(), any());
    } else {
        // load table from catalog
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, RESOURCE_PATHS.table(TBL), expectedContextHeaders), eq(LoadTableResponse.class), any(), any());
        // refresh loaded table
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, RESOURCE_PATHS.table(TBL), expectedTableHeaders), eq(LoadTableResponse.class), any(), any());
    }
}

