@Test
public void testReconcileOnUnknownSnapshotAddMatchesSnapshotId() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO"));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    catalog.createTable(TABLE, SCHEMA);
    // Simulate: server commits, but client receives CommitStateUnknown (transient 5xx)
    Mockito.doAnswer(invocation -> {
        invocation.callRealMethod();
        throw new CommitStateUnknownException(new ServiceFailureException("Service failed: 503"));
    }).when(adapter).execute(reqMatcher(HTTPMethod.POST, RESOURCE_PATHS.table(TABLE)), eq(LoadTableResponse.class), any(), any());
    Table table = catalog.loadTable(TABLE);
    // Perform a snapshot-adding commit; should reconcile instead of failing
    table.newFastAppend().appendFile(FILE_A).commit();
    // Extract the snapshot id we attempted to commit from the request body
    long expectedSnapshotId = allRequests(adapter).stream().filter(r -> r.method() == HTTPMethod.POST && r.path().equals(RESOURCE_PATHS.table(TABLE))).map(HTTPRequest::body).filter(UpdateTableRequest.class::isInstance).map(UpdateTableRequest.class::cast).map(req -> (MetadataUpdate.AddSnapshot) req.updates().stream().filter(u -> u instanceof MetadataUpdate.AddSnapshot).findFirst().orElseThrow()).map(add -> add.snapshot().snapshotId()).findFirst().orElseThrow();
    Table reloaded = catalog.loadTable(TABLE);
    assertThat(reloaded.currentSnapshot()).isNotNull();
    assertThat(reloaded.snapshot(expectedSnapshotId)).isNotNull();
}

