@ValueSource(ints = { 21, 30 })
public void testPaginationForListViews(int numberOfItems) {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(RESTCatalogProperties.PAGE_SIZE, "10"));
    String namespaceName = "newdb";
    String viewName = "newview";
    // create initial namespace
    catalog().createNamespace(Namespace.of(namespaceName));
    // create several views under namespace, based off a table for listing and verify
    for (int i = 0; i < numberOfItems; i++) {
        TableIdentifier viewIndentifier = TableIdentifier.of(namespaceName, viewName + i);
        catalog.buildView(viewIndentifier).withSchema(SCHEMA).withDefaultNamespace(viewIndentifier.namespace()).withQuery("spark", "select * from ns.tbl").create();
    }
    List<TableIdentifier> views = catalog.listViews(Namespace.of(namespaceName));
    assertThat(views).hasSize(numberOfItems);
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, "v1/config"), eq(ConfigResponse.class), any(), any());
    Mockito.verify(adapter, times(numberOfItems)).execute(reqMatcher(HTTPMethod.POST, String.format("v1/namespaces/%s/views", namespaceName)), eq(LoadViewResponse.class), any(), any());
    // verify initial request with empty pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
    // verify second request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "10", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
    // verify third request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_VIEWS), eq(ImmutableMap.of("pageToken", "20", "pageSize", "10", "namespace", namespaceName)), any(), eq(ListTablesResponse.class), any());
