public void testCatalogCredential(String oauth2ServerUri) {
    Map<String, String> emptyHeaders = ImmutableMap.of();
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer client-credentials-token:sub=catalog");
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, "ignored", "credential", "catalog:secret", OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri));
    assertThat(catalog.tableExists(TBL)).isFalse();
    // no token or credential for catalog token exchange
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, emptyHeaders), eq(OAuthTokenResponse.class), any(), any());
    // no token or credential for config
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), catalogHeaders), eq(ConfigResponse.class), any(), any());
    // use the catalog token for all interactions
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.HEAD, RESOURCE_PATHS.table(TBL), catalogHeaders), any(), any(), any());
}

