@ParameterizedTest
@ValueSource(strings = { "1", "2" })
public void testTableSnapshotLoadingWithDivergedBranches(String formatVersion) {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(CatalogProperties.URI, "ignored", CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.inmemory.InMemoryFileIO", RESTCatalogProperties.SNAPSHOT_LOADING_MODE, SnapshotMode.REFS.name()));
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    Table table = catalog.createTable(TABLE, SCHEMA, PartitionSpec.unpartitioned(), ImmutableMap.of("format-version", formatVersion));
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    String branch = "divergedBranch";
    table.manageSnapshots().createBranch(branch, table.currentSnapshot().snapshotId()).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-c.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    ResourcePaths paths = ResourcePaths.forCatalogProperties(Maps.newHashMap());
    Table refsTable = catalog.loadTable(TABLE);
    // don't call snapshots() directly as that would cause to load all snapshots. Instead,
    // make sure the snapshots field holds exactly 2 snapshots
    assertThat(((BaseTable) refsTable).operations().current()).extracting("snapshots").asInstanceOf(InstanceOfAssertFactories.list(Snapshot.class)).hasSize(2);
    assertThat(refsTable.currentSnapshot()).isEqualTo(table.currentSnapshot());
    // verify that the table was loaded with the refs argument
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "refs")), eq(LoadTableResponse.class), any(), any());
    // verify that all snapshots are loaded when referenced
    assertThat(catalog.loadTable(TABLE).snapshots()).containsExactlyInAnyOrderElementsOf(table.snapshots());
    verify(adapter, times(1)).execute(reqMatcher(HTTPMethod.GET, paths.table(TABLE), Map.of(), Map.of("snapshots", "all")), eq(LoadTableResponse.class), any(), any());
    // verify that committing to branch is possible
    catalog.loadTable(TABLE).newAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-c.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).toBranch(branch).commit();
    assertThat(catalog.loadTable(TABLE).snapshots()).hasSizeGreaterThan(Lists.newArrayList(table.snapshots()).size());
}

