@ParameterizedTest
@ValueSource(strings = { "v1/oauth/tokens", "https://auth-server.com/token" })
public void testCatalogExpiredBearerTokenIsRefreshedWithCredential(String oauth2ServerUri) {
    // expires at epoch second = 1
    String token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjF9.gQADTbdEv-rpDWKSkGLbmafyB5UUjTdm9B_1izpuZ6E";
    Map<String, String> emptyHeaders = ImmutableMap.of();
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer client-credentials-token:sub=catalog");
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    String credential = "catalog:12345";
    Map<String, String> contextCredentials = ImmutableMap.of("token", token);
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", contextCredentials, ImmutableMap.of());
    RESTCatalog catalog = new RESTCatalog(context, (config) -> adapter);
    // the init token at the catalog level is a valid token
    catalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, "ignored", "credential", credential, OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri));
    assertThat(catalog.tableExists(TBL)).isFalse();
    // call client credentials with no initial auth
    Map<String, String> clientCredentialsRequest = ImmutableMap.of("grant_type", "client_credentials", "client_id", "catalog", "client_secret", "12345", "scope", "catalog");
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, emptyHeaders, Map.of(), clientCredentialsRequest), eq(OAuthTokenResponse.class), any(), any());
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), catalogHeaders), eq(ConfigResponse.class), any(), any());
    Map<String, String> firstRefreshRequest = ImmutableMap.of("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange", "subject_token", token, "subject_token_type", "urn:ietf:params:oauth:token-type:access_token", "scope", "catalog");
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, OAuth2Util.basicAuthHeaders(credential), Map.of(), firstRefreshRequest), eq(OAuthTokenResponse.class), any(), any());
    // verify that a second exchange occurs
    Map<String, String> secondRefreshRequest = ImmutableMap.of("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange", "subject_token", token, "subject_token_type", "urn:ietf:params:oauth:token-type:access_token", "scope", "catalog");
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, OAuth2Util.basicAuthHeaders(credential), Map.of(), secondRefreshRequest), eq(OAuthTokenResponse.class), any(), any());
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.HEAD, RESOURCE_PATHS.table(TBL), Map.of("Authorization", "Bearer token-exchange-token:sub=" + token)), any(), any(), any());
}

